// @vitest-environment happy-dom
//
// The /verify pages (build spec T2, item 10), as generated by
// scripts/_build_verify_pages.py into the landing site. In all 9 locales
// they use the PDF's own file names and `base64 -d` (no more copy-pasting
// the wrapped payload text), give certutil for cmd and PowerShell, check
// the chain with parent_payload_sha256, and re-hash photos from the
// evidence file. The commands name fields the evidence file really has.
// When Python is on the PATH, the generator's --check confirms the pages
// on disk are exactly what it renders (CI's ubuntu runner has python3).
import { describe, expect, it } from 'vitest'
import type { ParkingSession, SignatureBundle } from '../types'
import { buildEvidenceFile } from './evidence-bundle'

const LOCALES = ['en', 'zh-CN', 'vi', 'id', 'ko', 'it', 'el', 'hi', 'pa'] as const
const VERIFY_DIR = 'migrations/two-app-architecture/landing-from-claude-design/verify'

type Fs = { readFileSync: (p: string, enc: 'utf8') => string }
type ChildProcess = {
  spawnSync: (cmd: string, args: string[], opts: { cwd: string; encoding: 'utf8' }) => { status: number | null; stdout: string; stderr: string; error?: Error }
}

const cwd = () => (globalThis as unknown as { process: { cwd: () => string } }).process.cwd()

async function page(locale: string): Promise<string> {
  // node:fs through a dynamic import, so the browser tsconfig needs no Node types.
  const fs = (await import('node:fs' as string)) as Fs
  const path = locale === 'en' ? `${VERIFY_DIR}/index.html` : `${VERIFY_DIR}/${locale}/index.html`
  return fs.readFileSync(`${cwd()}/${path}`, 'utf8').replace(/\r\n/g, '\n')
}

/** The text of every <pre> block: the commands, verbatim. */
function preBlocks(html: string): string {
  return [...html.matchAll(/<pre>([\s\S]*?)<\/pre>/g)].map((m) => m[1].replace(/<[^>]+>/g, '')).join('\n')
}

describe('the generated /verify pages', () => {
  for (const locale of LOCALES) {
    it(`${locale}: decodes the PDF's base64 blocks, checks the chain and re-hashes photos from the evidence file`, async () => {
      const html = await page(locale)
      const commands = preBlocks(html)
      expect(html).toContain(`<html lang="${locale}">`)
      // The signature check, with the PDF's file names and base64 -d.
      expect(commands).toContain('base64 -d link0-payload.b64 > link0-payload.txt')
      expect(commands).toContain('base64 -d link0-sig.b64 > link0-sig.bin')
      expect(commands).toContain('openssl dgst -sha256 -verify parkproof-public-key.pem \\\n  -signature link0-sig.bin link0-payload.txt')
      // Windows: certutil in cmd and PowerShell, curl.exe in PowerShell.
      expect(commands).toContain('certutil -decode link0-payload.b64 link0-payload.txt')
      expect(commands).toContain('certutil -decode link0-sig.b64 link0-sig.bin')
      expect(commands).toContain('curl.exe -O https://www.parkproof.com.au/parkproof-public-key.pem')
      expect(commands).toContain('certutil -hashfile photo1.jpg SHA256')
      // The chain step.
      expect(commands).toContain('openssl dgst -sha256 link0-payload.txt')
      expect(html).toContain('<code>parent_payload_sha256</code>')
      // The photo step, from the evidence file.
      expect(commands).toContain("jq -r '.photos[0].bytes_base64' evidence.json | base64 -d > photo1.jpg")
      expect(commands).toContain('openssl dgst -sha256 photo1.jpg')
      expect(commands).toContain('[Convert]::FromBase64String($e.photos[0].bytes_base64)')
      // The out-of-date copy-paste step is gone: no payload.txt pasted by hand, no sig.base64.
      expect(html).not.toContain('sig.base64')
      expect(commands).not.toContain('-signature sig.bin payload.txt')
      expect(commands).not.toMatch(/^sha256sum /m)
      // Copy rules.
      expect(html).not.toContain(String.fromCharCode(0x2014)) // no em-dash
      expect(html).not.toContain(String.fromCharCode(0xfffd)) // no replacement character
    })
  }

  // Copy rule: wherever signed material is presented, say a signature doesn't
  // show where the car was. Link 0 signs coordinates and an address, so a
  // reader who gets "Verified OK" must not take the location as established.
  const WHERE_THE_CAR_WAS: Record<(typeof LOCALES)[number], string> = {
    en: 'where the car was',
    'zh-CN': '车停在哪里',
    vi: 'xe ở đâu',
    id: 'di mana mobil berada',
    ko: '차가 어디에 있었는지',
    it: "dove si trovava l'auto",
    el: 'πού ήταν το αυτοκίνητο',
    hi: 'कार कहाँ थी',
    pa: 'ਕਾਰ ਕਿੱਥੇ ਸੀ',
  }
  for (const locale of LOCALES) {
    it(`${locale}: the callout and the "what a signature doesn't show" list both say it doesn't show where the car was`, async () => {
      const html = (await page(locale)).toLowerCase()
      const phrase = WHERE_THE_CAR_WAS[locale].toLowerCase()
      const callout = html.match(/<div class="callout">([\s\S]*?)<\/div>/)?.[1] ?? ''
      expect(callout).toContain(phrase)
      // The last list on the page is "Beyond 'did the bytes change?'"; its last item covers place, times and driver.
      const lists = [...html.matchAll(/<ul>([\s\S]*?)<\/ul>/g)].map((m) => m[1])
      const items = [...(lists[lists.length - 1] ?? '').matchAll(/<li>([\s\S]*?)<\/li>/g)].map((m) => m[1])
      expect(items).toHaveLength(4)
      expect(items[3]).toContain(phrase)
    })
  }

  it('every page has the same commands (only the comments are translated)', async () => {
    const strip = (s: string) => s.replace(/^#.*$/gm, '').replace(/\n+/g, '\n').trim()
    const en = strip(preBlocks(await page('en')))
    for (const locale of LOCALES) expect(strip(preBlocks(await page(locale)))).toBe(en)
  })

  it('the commands name fields a real evidence file has', async () => {
    const commands = preBlocks(await page('en'))
    const paths = [...commands.matchAll(/\.(photos|links)\[0\]\.([a-z0-9_]+)/g)].map(
      (m) => [m[1] as 'photos' | 'links', m[2]] as const,
    )
    expect(paths.length).toBeGreaterThan(4)

    const sha = 'ab'.repeat(32)
    const payload = { schema: 'parkproof-evidence-v2', session_id: 'rec-1', signed_at: '2026-11-08T01:00:04.000Z', sign_photo_sha256: sha }
    const link0: SignatureBundle = {
      schema: 'parkproof-evidence-v2',
      signed_at: payload.signed_at,
      algorithm: 'ECDSA_SHA_256',
      key_alias: 'alias/parkproof-evidence-signing',
      canonical_payload: JSON.stringify(payload),
      signature_base64: 'MEUCIQ',
    }
    const session = {
      id: 'rec-1',
      arrived_at: '2026-11-08T01:00:00.000Z',
      location: null,
      sign_photo: null,
      car_photo: null,
      rules: '2P',
      observations: [],
      expires_at: null,
      confidence: 'high',
      signature: link0,
    } as unknown as ParkingSession
    const file = await buildEvidenceFile(session, { photoBytes: new Map(), includePermit: false, now: 0 })
    for (const [list, field] of paths) {
      const first = (file[list] as unknown as Array<Record<string, unknown>>)[0]
      expect(first, `${list}[0]`).toBeDefined()
      expect(Object.keys(first), `${list}[0].${field}`).toContain(field)
    }
    // The state a page names for a photo with no bytes is the one the file writes.
    expect(file.photos[0].bytes).toBe('not_on_this_device')
    expect(await page('en')).toContain('<code>not_on_this_device</code>')
  })

  it('the pages on disk are what the generator renders (python --check)', async () => {
    const cp = (await import('node:child_process' as string)) as ChildProcess
    const python = ['python3', 'python'].find((cmd) => {
      const probe = cp.spawnSync(cmd, ['--version'], { cwd: cwd(), encoding: 'utf8' })
      return !probe.error && probe.status === 0
    })
    if (!python) {
      console.warn('[verify-pages] no python on the PATH: skipped the generator --check')
      return
    }
    const run = cp.spawnSync(python, ['scripts/_build_verify_pages.py', '--check'], { cwd: cwd(), encoding: 'utf8' })
    expect(run.stdout + run.stderr).toContain('all 9 verify pages match')
    expect(run.status).toBe(0)
  }, 60_000) // spawns python; slow CI runners need more than the 5 s default
})
